  async function generateMissions(){if(busy)return;const ps=selectedSummary(),loc=data.locations,p=ps[0],l=loc.length?loc[Math.floor(Date.now()/86400000)%loc.length]:null;const system='你是 LOVE RECORD 的生活剧情编剧。请为用户和同行角色生成一个具体、温柔、有画面感、可继续发展的今日小事件。只输出 JSON，字段 title、description、opening、suggestedAction。opening 是 120-260 字中文小剧情，像视觉小说的场景片段；不要替用户决定台词、行动、想法或情绪。';const context={world:worldContext(),characters:ps,persona:personaContext(),locations:loc.map(x=>({name:x.name,type:x.type,description:x.description})),recentHistory:data.history.slice(-5).map(x=>({place:x.place,text:x.text})),today:new Date().toLocaleString('zh-CN')};const out=await callAPI(system,JSON.stringify(context),'正在为今天编写一个小故事…');if(!out)return;let j;try{j=JSON.parse(out.replace(/^```json\s*|^```|```$/g,'').trim())}catch{j={title:(p?p.name+' · ':'')+'今日小提案',description:out.slice(0,180),opening:out,suggestedAction:'回应这个瞬间'}}const mission={id:'mission-'+Date.now(),title:String(j.title||'今日小提案'),description:String(j.description||j.suggestedAction||''),opening:String(j.opening||''),status:'pending',createdAt:Date.now(),personId:p?.id||'',personName:p?.name||'',locationId:l?.id||''};data.missions.unshift(mission);addActivity('新事件提案',mission.title+'：'+mission.description,{kind:'event',personId:mission.personId,locationId:mission.locationId,status:'pending'});save();renderMissions();renderActivity();if(mission.opening){await appendHistory(l?.name||'今日生活',mission.opening,'今日提案：'+mission.title);openMiniStory(mission.title,mission.opening,mission.locationId,'今日提案')}toast('今日小故事已生成，并已保存到记忆。')}
