  async function saveCustomMission(){const title=$('lrSpaceMissionName').value.trim(),description=$('lrSpaceMissionDescription').value.trim();if(!title&&!description){toast('先写下你想发生的事件。');return}if(busy)return;const ps=selectedSummary();const system='你是 LOVE RECORD 的互动剧情编剧。用户提供了一个自定义事件，请把它扩写成可互动的小剧情。输出 JSON，字段 title、description、opening、suggestedAction。opening 为 120-300 字中文场景，含环境和角色自然回应，但不能替用户决定行动、台词、想法或情绪。尊重世界书、角色设定和用户自设。';const context={idea:{title,description},world:worldContext(),characters:ps,persona:personaContext(),recentHistory:data.history.slice(-8).map(x=>({place:x.place,text:x.text})),memories:(data.memoryEngine?.cards||[]).filter(x=>x.status!=='deleted').slice(-8).map(x=>({title:x.title,content:x.content}))};const out=await callAPI(system,JSON.stringify(context),'正在把你的想法写成小剧情…');if(!out)return;let j;try{j=JSON.parse(out.replace(/^```json\s*|^```|```$/g,'').trim())}catch{j={title:title||'自定义事件',description:description||out.slice(0,160),opening:out,suggestedAction:'继续这个瞬间'}}const mission={id:'mission-'+Date.now(),title:String(j.title||title||'自定义事件'),description:String(j.description||description||''),opening:String(j.opening||out),status:'accepted',createdAt:Date.now(),personId:data.selectedPeople[0]||'',personName:person(data.selectedPeople[0])?.name||'',locationId:data.currentLocation||''};data.missions.unshift(mission);addActivity('自定义剧情开始',mission.title+'：'+mission.description,{kind:'event',personId:mission.personId,locationId:mission.locationId});await appendHistory(locationById(mission.locationId)?.name||'生活事件',mission.opening,'自定义事件：'+mission.title);save();closeMissionEditor();renderMissions();renderActivity();openMiniStory(mission.title,mission.opening,mission.locationId,'自定义事件');toast('小剧情已生成并记入记忆。')}
